{
  "isolation_holds": false,
  "violations": [
    {
      "subject": "alpha",
      "tenant": "globex",
      "access": "read"
    },
    {
      "subject": "bravo",
      "tenant": "acme",
      "access": "read"
    }
  ],
  "assumptions": "The stated grants are complete: alpha is authorized only for acme, and bravo only for globex. The recorded responses accurately describe returned data and state changes. Under the specified oracle, cross-tenant writes rejected by business logic with no state change remain UNKNOWN despite HTTP 200 and are not listed as confirmed violations.",
  "rationale": "Both cross-tenant reads returned the other tenant's stored order state to an unauthorized principal, directly violating tenant isolation. The successful reads and writes within each principal's granted tenant are authorized."
}

